  "环形缓冲 {n} 条 · 支持主题过滤 / 暂停 / 导出 JSON · 时间范围过滤": "Ring buffer of {n} entries · topic filter / pause / export JSON · time-range filter",
  "Ubuntu {n}+ / GNOME {n}+ 的「桌面共享」就是 RDP({n})": "Ubuntu {n}+ / GNOME {n}+ \"Desktop Sharing\" is RDP ({n})",
  ": 控制台断线会自动重连 (最多 {n} 次); 顶部「居中/拉伸」随窗口自适应缩放。": ": the console reconnects automatically (up to {n} times); the top \"center/stretch\" scales with the window.",
  "Fonriv → SSH → PVE 节点 → 网络 → PBS 服务器 API ({n})": "Fonriv → SSH → PVE node → network → PBS server API ({n})",
  "重启会短暂断开连接 (约 {n}~{n} 秒), 完成后刷新页面即可; 传输中的任务会被中断": "Restarting briefly disconnects (about {n}-{n}s); refresh the page afterwards; running transfers will be interrupted",
  "• 群晖 DSM: Control Panel → Terminal → 启用 SSH（端口一般改成非 {n}）": "• Synology DSM: Control Panel → Terminal → enable SSH (usually move the port off {n})",
  "(Ubuntu {n}+ 桌面共享=RDP) · macOS 屏幕共享 · 任意 VNC/SSH。目标机无需装软件。": "(Ubuntu {n}+ desktop sharing = RDP) · macOS Screen Sharing · any VNC/SSH. No agent needed on targets.",
  "按服务器 / 功能页面 / 日期筛选（存储在浏览器 localStorage，每个 scope 保留 {n} 条最新）": "Filter by server / page / date (stored in browser localStorage, {n} latest kept per scope)",
  "· ACME: 需公网域名解析到本机 且 {n} 端口可达 (HTTP-{n} 验证), 建议先用测试环境跑通再切正式": "· ACME: needs a public domain pointing here and port {n} reachable (HTTP-{n} challenge); test in staging first, then switch to production",
  "按协议选: RDP 优先 FreeRDP {n} 后端, VNC/SSH 优先新版本 — 也可在上面「网关」里指定某一个。": "By protocol: RDP prefers the FreeRDP {n} backend, VNC/SSH prefer the newer one — or pin a specific one via \"Gateway\" above.",
  "上传/本地方向、源为目录且文件数达阈值时自动分 {n} 片并发；目录/单文件/低数量自动走单流。双向同步与双远端始终单流。": "Upload/local direction with a directory source above the file-count threshold auto-splits into {n} parallel shards; directories/single files/low counts stay single-stream. Two-way sync and dual-remote are always single-stream.",
  "：本工具内置 asyncio 调度器（30s tick · croniter），\n          支持 {n} 类 action：": ": this tool ships a built-in asyncio scheduler (30s tick · croniter) with {n} action types:",
  "：传输前扫描源总量，≥ 阈值自动选用 rclone 并行（大文件实测更快），否则 rsync（万级小文件实测快 {n}~{n} 倍）。": ": scans total source size before transfer; at/above the threshold it switches to parallel rclone (faster for large files), otherwise rsync (measured {n}-{n}x faster for tens of thousands of small files).",
  "v5.14 · Merkle 树完整性 + AES-{n} + RSA-PSS 签名 (v1 包 HMAC 兼容) · {n} 天时效": "v5.14 · Merkle tree integrity + AES-{n} + RSA-PSS signature (HMAC-compatible with v1 packages) · {n}-day validity",
  "目标机已开标准 VNC (x11vnc / tigervnc, 端口 {n}) 时最省事; Wayland 桌面请改用 RDP 控制台。": "Easiest when the target runs standard VNC (x11vnc/tigervnc, port {n}); for Wayland desktops use the RDP console instead.",
  "dump | 压缩 | AES-{n} 加密 > 产物, 并生成 .sha256 校验文件; 恢复走反向管道 (解密 → 解压 → 导入)": "dump | compress | AES-{n} encrypt > artifact, plus a .sha256 checksum file; restore runs the reverse pipeline (decrypt → extract → import)",
  "（rsync / rclone / 并行分片 三引擎通用）；限速留空 = 该时段不限速；支持跨午夜（如 {n}–{n}）。未命中时段走手动带宽设置。": "(applies to all three engines: rsync / rclone / parallel shards); leave the rate blank for unlimited in that slot; cross-midnight supported (e.g. {n}-{n}). Unmatched slots fall back to the manual bandwidth setting.",
  "Linux 开 VNC: 装 x11vnc/tigervnc 并开放 {n}; macOS: 系统设置→共享→屏幕共享; 连接走服务端桥接, 目标无需暴露公网": "Linux VNC: install x11vnc/tigervnc and open {n}; macOS: System Settings → Sharing → Screen Sharing; connections are bridged server-side, targets need no public exposure",
  "apt install x11vnc && x11vnc -display :{n} -forever -shared -rfbport {n} -passwd 你的密码": "apt install x11vnc && x11vnc -display :{n} -forever -shared -rfbport {n} -passwd YOURPASSWORD",
  "— 用上方「RDP/VNC/SSH 远程控制台」直连 GNOME「设置 → 共享 → 桌面共享」(Ubuntu {n}+ 就是 RDP {n} 已实测可用);\n        ②": "— use the RDP/VNC/SSH remote console above to connect to GNOME \"Settings → Sharing → Desktop Sharing\" (Ubuntu {n}+ is RDP {n}, verified working);\n        ②",
  ", 没有 VNC {n} — 这类目标必须走本卡。\n          Windows 开启「允许远程桌面」、macOS 开启「屏幕共享」同理。协议由 guacd 转换, 浏览器端渲染。": ", no VNC {n} — such targets must go through this card.\n          Windows \"Allow Remote Desktop\" and macOS \"Screen Sharing\" work the same way. guacd converts the protocol; rendering happens in the browser.",
  "· 启用后 HTTPS 监听「HTTPS 端口」(默认 {n}), 原 WEB 端口自动变成跳转口: http://ip:{n} → https://ip:{n} (旧书签零修改); 浏览器 WebSocket 自动切 wss": "· When enabled, HTTPS listens on the \"HTTPS port\" (default {n}); the old web port becomes a redirect: http://ip:{n} → https://ip:{n} (bookmarks keep working); browser WebSocket switches to wss automatically",
  "💡 通过 SSH 在远端 Linux 上执行数据库客户端 (mysqldump 等, 复用其本机 socket, 数据不过明文网络);\n          产物经 rsync 通道回到落盘目录。适合数据库只监听 {n} 的默认安全配置。": "💡 Runs database clients (mysqldump etc.) on the remote Linux via SSH, reusing its local socket — data never crosses the network in plaintext;\n          artifacts come back through the rsync channel to the output directory. Ideal when the database only listens on {n} (default secure setup).",
