  "流程: 两端分别登记候选地址 (控制面自动填入观测到的来源地址) → 并发探测候选可达性 →\n        可行则建立直连 (数据不经控制面), 全不可达则**自动回退中继转发**并启用 L2 暂存加密。\n        本实现为应用层地址协商 + 并发可达性探测; 对称型网络地址转换场景下会如实回退, 不谎报直连成功。": "Flow: both ends register candidate addresses (control plane auto-fills observed source addresses) → probes candidates concurrently →\n        establishes a direct link when possible (data bypasses the control plane); if nothing is reachable it **automatically falls back to relay forwarding** with L2 transit encryption.\n        Implementation is application-layer address negotiation + concurrent reachability probing; under symmetric NAT it honestly falls back instead of faking a direct link.",
  "流程: 导出方出示公钥 → 带外复制 (U盘/纸质) → 导入方录入信任列表": "Flow: exporter presents the public key → out-of-band copy (USB/paper) → importer enters it into the trust list",
