  "把传输项桥接到『跨模块自动备份』流程（本地/SSH 源 -> ☁ 远端存储目标，支持定时调度） ": "Bridge transfer items into the『Cross-module Auto Backup』flow (local/SSH source → ☁ remote storage target, schedulable)",
  "双向同步（两侧新增/修改的文件互相同步 · 同名冲突较新者胜 · 删除不传播 · v4.51 真双向） ": "Two-way sync (new/changed files sync both ways · newest wins on name conflicts · deletions do not propagate · true two-way since v4.51)",
  "Windows 空密码账号在 NLA(自动协商) 下会被要求交互补凭据 → 一直黑屏; 实测必须用 TLS": "Windows accounts with blank passwords get stuck at NLA (auto-negotiate) credential prompts → endless black screen; verified: must use TLS",
  "例: 每天凌晨2点把 /opt/data 备份到 /opt/backups 并保留14天 (Enter 发送)": "e.g. back up /opt/data to /opt/backups daily at 2am keeping 14 days (Enter to send)",
  "v4.92 · D2: 探测路径所在存储栈, 自动推荐备份通道 (zfs send/LVM快照/rbd/rsync)": "v4.92 · D2: probe the path's storage stack and recommend a backup channel (zfs send / LVM snapshot / rbd / rsync)",
  "HTTPS 实际监听端口; 与 WEB 端口不同时, 原端口自动做 HTTP→HTTPS 301 跳转 (旧书签无需修改)": "Actual HTTPS listen port; when different from the web port, the old port auto-redirects HTTP→HTTPS 301 (bookmarks need no change)",
  "-----BEGIN PRIVATE KEY-----\n私钥 PEM (仅存本机 data/https/, 权限 600)…": "-----BEGIN PRIVATE KEY-----\nPrivate key PEM (stored only in local data/https/, mode 600)…",
  "本机作为服务端对外暴露的协议 — 供手机/鸿蒙/NAS/电视等设备反向访问本机文件; 可用项按本机 rclone 实际能力探测": "Protocols this machine exposes as a server — for phones/HarmonyOS/NAS/TVs to reach local files in reverse; available items probed per local rclone capabilities",
  "决定 RDP 兼容性: FreeRDP 2 (1.5.x) 兼容性最好; FreeRDP 3 (1.6.x) 在新 FreeRDP 上实测不出图像帧": "Determines RDP compatibility: FreeRDP 2 (1.5.x) is the most compatible; FreeRDP 3 (1.6.x) verifiably produces no video frames on newer FreeRDP",
  "Windows → FreeRDP 3 后端; Linux(xrdp) → FreeRDP 2 后端 (实测 Windows 黑屏时也试 Linux)": "Windows → FreeRDP 3 backend; Linux (xrdp) → FreeRDP 2 backend (when Windows shows a black screen, try Linux too)",
