  "xrdp 会按 (账号 + 分辨率) 复用会话; 若目标机已有该账号的残留会话且已息屏, 复用后会全黑。勾选后用一个 1px 偏差的分辨率强制新建会话。": "xrdp reuses sessions by (account + resolution); if the target already has a stale screen-locked session for that account, reuse shows a black screen. Checking this forces a new session with a 1px-offset resolution.",
